using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ───────────────────────────────────────────────
    //  CalculateTotal – DataRow (compile-time data)
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0,  10.00,  DisplayName = "Single item, no tax")]
    [DataRow(10.00, 2, 0.0,  20.00,  DisplayName = "Two items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00,  DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62,  DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00,  5, 0.10,  0.00,  DisplayName = "Zero price yields zero total")]
    [DataRow(99.99, 0, 0.15,  0.00,  DisplayName = "Zero quantity yields zero total")]
    public void CalculateTotal_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // ───────────────────────────────────────────────
    //  CalculateTotal – invalid inputs throw
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(-1.00, 1,  0.10, DisplayName = "Negative unit price")]
    [DataRow(10.00, -1, 0.10, DisplayName = "Negative quantity")]
    [DataRow(10.00, 1,  -0.1, DisplayName = "Negative tax rate")]
    [DataRow(10.00, 1,  1.5,  DisplayName = "Tax rate above 1")]
    public void CalculateTotal_InvalidInputs_Throws(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    // ───────────────────────────────────────────────
    //  ApplyDiscount – DynamicData (runtime data)
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> DiscountTestData =>
    [
        [100.00m,  0m,   100.00m, "No discount"],
        [100.00m, 10m,    90.00m, "10% off"],
        [100.00m, 50m,    50.00m, "50% off"],
        [100.00m, 100m,    0.00m, "100% off"],
        [59.99m,  15m,   50.9915m, "Fractional result"],
        [0.00m,   25m,    0.00m, "Zero price stays zero"],
    ];

    [TestMethod]
    [DynamicData(nameof(DiscountTestData), DynamicDataDisplayName = nameof(GetDiscountDisplayName))]
    public void ApplyDiscount_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected, string scenario)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static string GetDiscountDisplayName(MethodInfo methodInfo, object[] data) =>
        $"{methodInfo.Name}: {(string)data[3]}";

    // ───────────────────────────────────────────────
    //  ApplyDiscount – boundary / invalid discounts
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(-1.0,  DisplayName = "Discount below 0")]
    [DataRow(100.1, DisplayName = "Discount above 100")]
    public void ApplyDiscount_InvalidDiscount_Throws(double discount)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, (decimal)discount));
    }

    // ───────────────────────────────────────────────
    //  FormatPrice – DataRow
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(19.99,  "$",  "$19.99",  DisplayName = "USD format")]
    [DataRow(19.99,  "€",  "€19.99",  DisplayName = "EUR format")]
    [DataRow(5.1,    "$",  "$5.10",   DisplayName = "Pads to two decimals")]
    [DataRow(0.0,    "£",  "£0.00",   DisplayName = "Zero in GBP")]
    public void FormatPrice_ReturnsExpected(
        double price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice((decimal)price, symbol);

        Assert.AreEqual(expected, result);
    }
}

